pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items == 0 {
        1.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };
    let inv_progress = 1.0 - progress;
    let capacity = bin_capacity.max(1) as f64;
    let normalized_post = post_residual as f64 / capacity;
    let normalized_item = item_size as f64 / capacity;
    let normalized_next = next_item_size as f64 / capacity;
    let mean_norm = (mean_residual / capacity).clamp(0.0, 1.0);
    let fit_ratio = if fitting_bins_count == 0 {
        0.0
    } else {
        1.0 / (fitting_bins_count as f64).sqrt()
    };

    let mut score = post_residual as f64;
    score -= 28.0 * progress * progress * normalized_post * normalized_post;
    score += 42.0 * inv_progress * normalized_post * normalized_post;
    score += 15.0 * normalized_post * normalized_item * normalized_item;
    score -= 9.0 * normalized_next * mean_norm;
    score += 6.0 * normalized_item * (1.0 - mean_norm) * (1.0 - fit_ratio);
    score -= 4.0 * open_bins_count as f64 * normalized_post * inv_progress;
    score += 12.0 * (1.0 - fitting_bins_count as f64 / (open_bins_count.max(1) as f64)).clamp(0.0, 1.0) * normalized_post;
    score
