pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let mean = mean_residual.max(0.0);
    let next = next_item_size as f64;
    let progress = if total_items == 0 {
        0.0
    } else {
        step_index as f64 / total_items as f64
    };

    let new_bin = bin_residual >= bin_capacity;
    let post_fraction = post / capacity;
    let item_fraction = item / capacity;
    let mean_fraction = (mean / capacity).min(1.0);

    let mut harmonic = 0.0;
    if post > 0 {
        harmonic += 1.0 / (1.0 + post_fraction);
        harmonic += (post as u32 % 10) as f64 * 0.025;
        harmonic += (post as u32 % 25) as f64 * 0.012;
    } else {
        harmonic -= 2.0;
    }

    if next > 0 {
        let next_fits = (next <= post) as u32;
        harmonic += next_fits as f64 * 0.55;
        harmonic -= (next / capacity) * 0.35;
        let gap = (post as i64 - next as i64).abs() as f64;
        harmonic += gap / capacity * 0.20;
    }

    harmonic -= post_fraction * 0.45;
    harmonic -= (mean_fraction - post_fraction).abs() * 0.15;
    harmonic += (1.0 - progress) * 0.08;

    if fitting_bins_count <= 1 && !new_bin {
        harmonic -= 0.75;
    }

    if new_bin {
        harmonic += 0.90;
        harmonic -= open_bins_count as f64 * 0.002;
        harmonic += item_fraction * 0.20;
    }

    score = harmonic;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let dead_space_limit = (next_item_size as f64 * 0.75).max(8.0);
    if (post_residual as f64) < dead_space_limit {
        score += (dead_space_limit - post_residual as f64) * 3.5;
    } else {
        score += (post_residual as f64) * 0.08;
    }

    if post_residual == 0 {
        score -= 18.0;
    } else if post_residual < item_size {
        score -= 7.0;
    }

    if next_item_size == 0 {
        score -= post_residual as f64 * 0.12;
    } else if post_residual >= next_item_size {
        score -= 4.0;
    } else {
        score += (next_item_size - post_residual) as f64 * 0.55;
    }

    score += ((open_bins_count as f64).max(1.0) - 1.0).sqrt() * 1.8;
    score += (mean_residual - post_residual as f64) * 0.045;

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score += 7.5;
    }

    if bin_residual == bin_capacity {
        score += 28.0;
        score += open_bins_count as f64 * 0.65;
    }

    let progress = if total_items == 0 {
        0.0
    } else {
        step_index as f64 / total_items as f64
    };
    score += progress * 0.8;

    score
}
